import { readFileSync } from "node:fs";
import { join } from "node:path";
import { loadManifest } from "../../lib/dataset";

export const metadata = { title: "Papers | CRUCIBLE" };

/** Minimal markdown rendering, deliberately.
 *
 *  A library would be a dependency carried for one document, and this document
 *  is generated by us from a template we control, so its markdown subset is
 *  known rather than arbitrary. */
function render(md: string) {
  const out: React.ReactNode[] = [];
  const lines = md.split("\n");
  let table: string[] = [];

  const flushTable = (key: number) => {
    if (table.length === 0) return;
    const cells = table.map((r) =>
      r.split("|").slice(1, -1).map((c) => c.trim()));
    const [head, , ...body] = cells;
    out.push(
      <div className="scroll-x" key={`t${key}`}>
        <table>
          <thead><tr>{head.map((h, i) => <th key={i}>{h}</th>)}</tr></thead>
          <tbody>
            {body.map((row, i) => (
              <tr key={i}>{row.map((c, j) => (
                <td key={j} className={j > 0 && /^\d+$/.test(c) ? "num" : ""}>{c}</td>
              ))}</tr>
            ))}
          </tbody>
        </table>
      </div>,
    );
    table = [];
  };

  lines.forEach((line, i) => {
    if (line.startsWith("|")) { table.push(line); return; }
    flushTable(i);
    if (line.startsWith("### ")) out.push(<h3 key={i}>{line.slice(4)}</h3>);
    else if (line.startsWith("## ")) out.push(<h2 key={i}>{line.slice(3)}</h2>);
    else if (line.startsWith("# ")) out.push(<h1 key={i}>{line.slice(2)}</h1>);
    else if (line.startsWith("- ")) out.push(<li key={i}>{emphasis(line.slice(2))}</li>);
    else if (line.startsWith("*") && line.endsWith("*") && line.length > 2)
      out.push(<p className="standfirst" key={i}>{line.slice(1, -1)}</p>);
    else if (line.trim()) out.push(<p key={i}>{emphasis(line)}</p>);
  });
  flushTable(lines.length);
  return out;
}

function emphasis(text: string) {
  return text.split(/(\*\*[^*]+\*\*)/g).map((part, i) =>
    part.startsWith("**") && part.endsWith("**")
      ? <strong key={i}>{part.slice(2, -2)}</strong>
      : <span key={i}>{part}</span>);
}

export default function Papers() {
  const m = loadManifest();
  const path = join(process.cwd(), "public", "papers", "container-viability.md");
  const paper = m.paper_published ? readFileSync(path, "utf8") : null;

  return (
    <div className="sheet page">
      <p className="label">Papers</p>

      {paper === null ? (
        <>
          <h1>No paper is currently published</h1>
          <p className="note">
            Generation refuses to emit a document when the record cannot support
            one, rather than publishing an empty template.
          </p>
        </>
      ) : (
        <>
          <p className="provenance">
            Generated from the dataset published{" "}
            <code>{m.generated_at.slice(0, 10)}</code>, engine{" "}
            <code>{m.engine_commit.slice(0, 12)}</code>. Every numeral in the
            text below was checked against the record before the document was
            emitted.{" "}
            <a href="/papers/container-viability.md" download>Download the source</a>
          </p>
          <article className="paper">{render(paper)}</article>
        </>
      )}

      <style>{`
        .page { padding: 3.5rem 0 1rem; }
        .provenance {
          font-size: var(--t-small);
          color: var(--ink-soft);
          border-top: var(--rule-hair) solid var(--ink);
          border-bottom: var(--rule-hair) solid var(--rule);
          padding: 0.9rem 0;
          margin: 0.7rem 0 2.5rem;
          max-width: none;
        }
        .paper { display: flex; flex-direction: column; gap: 1rem; }
        .paper h1 { margin: 0.5rem 0 0; max-width: 24ch; }
        .paper h2 {
          font-size: var(--t-h3);
          margin-top: 2rem;
          padding-bottom: 0.4rem;
          border-bottom: var(--rule-hair) solid var(--rule);
        }
        .paper h3 { font-size: var(--t-body); margin-top: 1.2rem; }
        .paper .standfirst {
          font-family: var(--font-display);
          font-style: italic;
          color: var(--ink-soft);
        }
        .paper li { margin-left: 1.2rem; max-width: var(--measure); }
        .note { font-size: var(--t-small); color: var(--ink-soft); }
      `}</style>
    </div>
  );
}
